\\"items\\\":{\\\"type\\\":\\\"object\\\",\\\"additionalProperties\\\":false,\\\"required\\\":[\\\"parent_ref\\\",\\\"intervention\\\",\\\"control\\\",\\\"held_fixed\\\",\\\"remaining_confounds\\\",\\\"decision_if_supported\\\",\\\"decision_if_not_supported\\\"],\\\"properties\\\":{\\\"parent_ref\\\":{\\\"type\\\":\\\"string\\\"},\\\"intervention\\\":{\\\"type\\\":\\\"string\\\"},\\\"control\\\":{\\\"type\\\":\\\"string\\\"},\\\"held_fixed\\\":{\\\"type\\\":\\\"array\\\",\\\"items\\\":{\\\"type\\\":\\\"string\\\"}},\\\"remaining_confounds\\\":{\\\"type\\\":\\\"array\\\",\\\"items\\\":{\\\"type\\\":\\\"string\\\"}},\\\"decision_if_supported\\\":{\\\"type\\\":\\\"string\\\"},\\\"decision_if_not_supported\\\":{\\\"type\\\":\\\"string\\\"}}}},\\\"cost_plan\\\":{\\\"type\\\":\\\"object\\\",\\\"additionalProperties\\\":false,\\\"required\\\":[\\\"estimate_ref\\\",\\\"all_variants_counted\\\",\\\"attribution_reserve\\\",\\\"assessment_reserve\\\",\\\"stop_rule\\\"],\\\"properties\\\":{\\\"estimate_ref\\\":{\\\"type\\\":\\\"string\\\"},\\\"all_variants_counted\\\":{\\\"const\\\":true},\\\"attribution_reserve\\\":{\\\"type\\\":\\\"string\\\"},\\\"assessment_reserve\\\":{\\\"type\\\":\\\"string\\\"},\\\"stop_rule\\\":{\\\"type\\\":\\\"string\\\"}}}}}\")
proposal = json.loads(Path('proposal.json').read_text())

def validate(value, spec, loc):
    types = {'object': dict, 'array': list, 'string': str, 'boolean': bool}
    if 'type' in spec:
        assert isinstance(value, types[spec['type']]), (loc, 'wrong type')
    if 'const' in spec:
        assert value == spec['const'], (loc, 'wrong constant')
    if 'enum' in spec:
        assert value in spec['enum'], (loc, 'wrong enum')
    if isinstance(value, dict):
        assert set(spec.get('required', [])) <= set(value), (loc, 'missing keys')
        if spec.get('additionalProperties') is False:
            assert set(value) <= set(spec.get('properties', {})), (loc, 'extra keys')
        for key, sub in spec.get('properties', {}).items():
            if key in value:
                validate(value[key], sub, loc + '.' + key)
    if isinstance(value, list):
        assert len(value) >= spec.get('minItems', 0), (loc, 'too few items')
        for i, item in enumerate(value):
            if 'items' in spec:
                validate(item, spec['items'], loc + '[' + str(i) + ']')
    if isinstance(value, str):
        assert len(value) >= spec.get('minLength', 0), (loc, 'string too short')

validate(proposal['study'], schema, 'study')
assert proposal['parent_trial'] == 'baseline-din'
assert proposal['study']['protocol_ref'] == '9c1635366a72f4c4f67708ee7ae9b72a1b90197ffed3485736388ceff7c91d3e'
variants = proposal['variants']
assert 1 <= len(variants) <= 4
assert len({v['name'] for v in variants}) == len(variants)
assert len({v['file'] for v in variants}) == len(variants)
assert any(v['role'] == 'candidate' for v in variants)
assert {(v['config']['grouping'], v['config']['normalization']) for v in variants} == {
    ('behavior', 'within_group'), ('behavior', 'global'),
    ('interleaved', 'within_group'), ('interleaved', 'global')}
hashes = set()
for variant in variants:
    name = variant['file']
    assert Path(name).name == name and name.endswith('.py')
    assert variant['role'] in ('candidate', 'control')
    source = Path(name).read_text()
    tree = ast.parse(source, filename=name)
    compile(tree, name, 'exec')
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            assert all(alias.name.split('.')[0] == 'torch' for alias in node.names)
        if isinstance(node, ast.ImportFrom):
            assert node.module == 'torch'
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
            assert node.func.id not in {'open', 'exec', 'eval', '__import__', 'compile'}
    model = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == 'Model')
    methods = {n.name for n in model.body if isinstance(n, ast.FunctionDef)}
    assert {'__init__', 'forward', 'diagnostics', '_represent'} <= methods
    config_node = next(n.value for n in tree.body if isinstance(n, ast.Assign)
                       and any(isinstance(t, ast.Name) and t.id == 'CONFIG' for t in n.targets))
    defaults = ast.literal_eval(config_node)
    merged = dict(defaults, **variant['config'])
    assert merged['embedding_dim'] == 16 and merged['hidden'] == [128, 64] and merged['lr'] == 0.001
    sha = hashlib.sha256(source.encode()).hexdigest()
    hashes.add(sha)
    assert sha in ' '.join(proposal['study']['inherited_components'])
    print(name + ': syntax/interface/source checks passed; sha256=' + sha)
assert len(hashes) == 1, 'Model source must match across factorial cells'
baseline_sha = hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()
assert baseline_sha == 'ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
assert {a['knowledge_id'] for a in proposal['knowledge_assessments']} == {
    'taac2026-academic-2-unidac', 'taac2026-industry-1-queryformer'}
print('Study schema, complete 2x2 factorial, source equality, configs and baseline integrity passed.')
print('No torch import, model execution, training or installation performed.')

PY"

